import{isroTimelineData}from"./data.js";(()=>{const e=document.getElementById("timeline-container");var t;t=isroTimelineData,e.innerHTML="",t.forEach(t=>{const a=document.createElement("article");a.className="timeline-item";const n=document.createElement("div");n.className="timeline-marker",n.setAttribute("aria-hidden","true");const i=document.createElement("div");i.className="timeline-content",i.setAttribute("tabindex","0");const s=document.createElement("div");s.className="timeline-year",s.textContent=t.year;const l=document.createElement("h3");l.className="timeline-title",l.textContent=t.mission;const c=document.createElement("figure");c.className="timeline-figure";const d=document.createElement("img");d.src=t.image,d.alt=`Illustration or photo of ${t.mission}`,d.loading="lazy",d.onerror=()=>{d.src="data:image/svg+xml;charset=UTF-8,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22400%22%20height%3D%22200%22%20viewBox%3D%220%200%20400%20200%22%3E%3Crect%20fill%3D%22%231C2541%22%20width%3D%22400%22%20height%3D%22200%22%2F%3E%3Ctext%20fill%3D%22%23E0E1DD%22%20font-family%3D%22sans-serif%22%20font-size%3D%2216%22%20dy%3D%228%22%20font-weight%3D%22bold%22%20x%3D%2250%25%22%20y%3D%2250%25%22%20text-anchor%3D%22middle%22%3EImage%20Unavailable%3C%2Ftext%3E%3C%2Fsvg%3E"},c.appendChild(d);const o=document.createElement("div");o.className="timeline-data",o.innerHTML=`\n        <div class="data-row">\n          <span class="data-label">Category:</span>\n          <span class="data-value">${t.category}</span>\n        </div>\n        <div class="data-row">\n          <span class="data-label">Vehicle:</span>\n          <span class="data-value">${t.vehicle}</span>\n        </div>\n        <div class="data-row">\n          <span class="data-label">Objective:</span>\n          <span class="data-value">${t.objective}</span>\n        </div>\n        <div class="data-row">\n          <span class="data-label">Outcome:</span>\n          <span class="data-value">${t.outcome}</span>\n        </div>\n      `;const m=document.createElement("p");m.textContent=t.description,m.style.color="var(--color-text-muted)",m.style.fontSize="0.95rem";const r=document.createElement("div");r.className="timeline-achievement",r.innerHTML=`\n        <strong>Achievement Highlight</strong>\n        <p>${t.achievement}</p>\n      `,i.appendChild(s),i.appendChild(l),i.appendChild(c),i.appendChild(o),i.appendChild(m),i.appendChild(r),a.appendChild(n),a.appendChild(i),e.appendChild(a)})})();